    73    Tag           tag;            /* 4-byte identifier. */
    74    CheckSum      checkSum;       /* CheckSum for this table. */
    75    Offset32      offset;         /* Offset from beginning of TrueType font
    76                                   * file. */
    77    HBUINT32      length;         /* Length of this table. */
