   481  /*
   482   * OpenType Font File
   483   */
   484
   485  struct OpenTypeFontFile
   486  {
   487    enum {
   488      CFFTag              = HB_TAG ('O','T','T','O'), /* OpenType with Postscript outlines */
   489      TrueTypeTag = HB_TAG ( 0 , 1 , 0 , 0 ), /* OpenType with TrueType outlines */
   490      TTCTag              = HB_TAG ('t','t','c','f'), /* TrueType Collection */
   491      DFontTag            = HB_TAG ( 0 , 0 , 1 , 0 ), /* DFont Mac Resource Fork */
   492      TrueTag             = HB_TAG ('t','r','u','e'), /* Obsolete Apple TrueType */
   493      Typ1Tag             = HB_TAG ('t','y','p','1')  /* Obsolete Apple Type1 font in SFNT container */
   494    };
   495
   496    inline hb_tag_t get_tag (void) const { return u.tag; }
   497
   498    inline unsigned int get_face_count (void) const
   499    {
   500      switch (u.tag) {
   501      case CFFTag:        /* All the non-collection tags */
   502      case TrueTag:
   503      case Typ1Tag:
   504      case TrueTypeTag:   return 1;
   505      case TTCTag:        return u.ttcHeader.get_face_count ();
   506  //    case DFontTag:    return u.rfHeader.get_face_count ();
   507      default:            return 0;
   508      }
   509    }
   510    inline const OpenTypeFontFace& get_face (unsigned int i) const
   511    {
   512      switch (u.tag) {
   513      /* Note: for non-collection SFNT data we ignore index.  This is because
   514       * Apple dfont container is a container of SFNT's.  So each SFNT is a
   515       * non-TTC, but the index is more than zero. */
   516      case CFFTag:        /* All the non-collection tags */
   517      case TrueTag:
   518      case Typ1Tag:
   519      case TrueTypeTag:   return u.fontFace;
   520      case TTCTag:        return u.ttcHeader.get_face (i);
   521  //    case DFontTag:    return u.rfHeader.get_face (i);
   522      default:            return Null(OpenTypeFontFace);
   523      }
   524    }
   525
   526    inline bool serialize_single (hb_serialize_context_t *c,
   527                                  hb_tag_t sfnt_tag,
   528                                  Supplier<hb_tag_t> &tags,
   529                                  Supplier<hb_blob_t *> &blobs,
   530                                  unsigned int table_count)
   531    {
   532      TRACE_SERIALIZE (this);
   533      assert (sfnt_tag != TTCTag);
   534      if (unlikely (!c->extend_min (*this))) return_trace (false);
   535      return_trace (u.fontFace.serialize (c, sfnt_tag, tags, blobs, table_count));
   536    }
   537
   538    inline bool sanitize (hb_sanitize_context_t *c) const
   539    {
   540      TRACE_SANITIZE (this);
   541      if (unlikely (!u.tag.sanitize (c))) return_trace (false);
   542      switch (u.tag) {
   543      case CFFTag:        /* All the non-collection tags */
   544      case TrueTag:
   545      case Typ1Tag:
   546      case TrueTypeTag:   return_trace (u.fontFace.sanitize (c));
   547      case TTCTag:        return_trace (u.ttcHeader.sanitize (c));
   548  //    case DFontTag:    return_trace (u.rfHeader.sanitize (c));
   549      default:            return_trace (true);
   550      }
   551    }
   552
   553    protected:
   554    union {
   555    Tag                   tag;            /* 4-byte identifier. */
   556    OpenTypeFontFace      fontFace;
   557    TTCHeader             ttcHeader;
   558    ResourceForkHeader    rfHeader;
   559    } u;
   560    public:
   561    DEFINE_SIZE_UNION (4, tag);
   562  };
