   701  template <typename T1, typename T2> struct hb_non_void_t { typedef T1 value; };
   702  template <typename T2> struct hb_non_void_t<void, T2> { typedef T2 value; };
   703
   704  template <typename Returned,
   705            typename Subclass = void,
   706            typename Data = void,
   707            unsigned int WheresData = 0,
   708            typename Stored = Returned>
   709  struct hb_lazy_loader_t : hb_data_wrapper_t<Data, WheresData>
   710  {
   711    typedef typename hb_non_void_t<Subclass,
   712                                   hb_lazy_loader_t<Returned,Subclass,Data,WheresData,Stored>
   713                                  >::value Funcs;
   714
   715    inline void init0 (void) {} /* Init, when memory is already set to 0. No-op for us. */
   716    inline void init (void) { instance.set_relaxed (nullptr); }
   717    inline void fini (void)
   718    {
   719      do_destroy (instance.get ());
   720    }
   721    inline void free_instance (void)
   722    {
   723    retry:
   724      Stored *p = instance.get ();
   725      if (unlikely (p && !this->instance.cmpexch (p, nullptr)))
   726        goto retry;
   727      do_destroy (p);
   728    }
   729
   730    inline Stored * do_create (void) const
   731    {
   732      Stored *p = this->template call_create<Stored, Funcs> ();
   733      if (unlikely (!p))
   734        p = const_cast<Stored *> (Funcs::get_null ());
   735      return p;
   736    }
   737    static inline void do_destroy (Stored *p)
   738    {
   739      if (p && p != Funcs::get_null ())
   740        Funcs::destroy (p);
   741    }
   742
   743    inline const Returned * operator -> (void) const { return get (); }
   744    inline const Returned & operator * (void) const { return *get (); }
   745
   746    inline Data * get_data (void) const
   747    {
   748      return *(((Data **) this) - WheresData);
   749    }
   750
   751    inline Stored * get_stored (void) const
   752    {
   753    retry:
   754      Stored *p = this->instance.get ();
   755      if (unlikely (!p))
   756      {
   757        p = do_create ();
   758        if (unlikely (!this->instance.cmpexch (nullptr, p)))
   759        {
   760          do_destroy (p);
